#define DUREE_JOURNEE 90.

#define C_BASE -.26
#define C_TAILLE .115
#define C_GRAINE 3.

float gJour, gNuit, gCrepuscule, gAngleJour;
vec2  gSoleil, gLune, gDirectionLumiere;
vec3  gHorizon, gMilieu, gSommet, gCouleurSoleil;

float hachage11(float p){ p = fract(p*.1031); p *= p+33.33; p *= p+p; return fract(p); }
float hachage21(vec2 p){ vec3 p3 = fract(vec3(p.xyx)*.1031); p3 += dot(p3, p3.yzx+33.33); return fract((p3.x+p3.y)*p3.z); }
vec2  hachage22(vec2 p){ float n = hachage21(p); return vec2(n, hachage21(p+n*17.3)); }

float bruit(vec2 p){
    vec2 i = floor(p), f = fract(p);
    f = f*f*(3.-2.*f);
    return mix(mix(hachage21(i), hachage21(i+vec2(1,0)), f.x),
               mix(hachage21(i+vec2(0,1)), hachage21(i+vec2(1,1)), f.x), f.y);
}
float fbm(vec2 p){
    float a = .5, s = 0.;
    for(int i=0;i<4;i++){ s += a*bruit(p); p = p*2.03+7.1; a *= .5; }
    return s;
}

void configurerEclairage(float t)
{
    float a  = 2.2 + t*6.28318/DUREE_JOURNEE;
    float sa = sin(a);
    gAngleJour = mod(a - 1.5707963, 6.2831853) - 3.1415927;

    gSoleil = vec2(-.7*cos(a),  .38*sa + .08);
    gLune   = vec2( .7*cos(a), -.34*sa + .08);

    gJour       = smoothstep(-.12, .30, sa);
    gNuit       = 1. - gJour;
    gCrepuscule = exp(-sa*sa*12.);

    vec3 jourH = vec3(.80,.90,1.00), jourM = vec3(.40,.65,.95), jourT = vec3(.18,.40,.85);
    vec3 nuitH = vec3(.38,.22,.60), nuitM = vec3(.12,.08,.35), nuitT = vec3(.03,.025,.15);
    vec3 crepH = vec3(1.0,.48,.30), crepM = vec3(.75,.28,.50), crepT = vec3(.15,.10,.40);
    gHorizon = mix(mix(nuitH, jourH, gJour), crepH, gCrepuscule);
    gMilieu  = mix(mix(nuitM, jourM, gJour), crepM, gCrepuscule);
    gSommet  = mix(mix(nuitT, jourT, gJour), crepT, gCrepuscule);

    gCouleurSoleil = mix(vec3(1.,.95,.80), vec3(1.,.50,.20), clamp(gCrepuscule*1.5, 0., 1.));

    vec2 posLumiere = mix(gLune, gSoleil, smoothstep(.3, .7, gJour));
    gDirectionLumiere = normalize(posLumiere - vec2(0., -.15));
}

vec3 palette(vec3 c)
{
    vec3 d = vec3(c.g*.9 + .02, c.g*1.7 + .08, c.b*.4 + .02);
    vec3 r = mix(c, d, gJour);
    r = mix(r, r*vec3(1.4,.85,.7), gCrepuscule*.7);
    return r;
}

float sdSegment(vec2 p, vec2 a, vec2 b, float r)
{
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba)/dot(ba, ba), 0., 1.);
    return length(pa - ba*h) - r;
}

float sdAile(vec2 p, vec2 h, float th, float L, float wd)
{
    vec2 d = p - h;
    float c = cos(th), s = sin(th);
    vec2 w = vec2(c*d.x + s*d.y, -s*d.x + c*d.y);
    return (length((w - vec2(L, 0.))/vec2(L, wd)) - 1.)*wd;
}

vec3 fee(vec2 p, vec3 col, float t)
{
    float LARGEUR = .28;
    float fenetre = 1. - smoothstep(LARGEUR*.8, LARGEUR, abs(gAngleJour));
    if(fenetre <= 0.) return col;

    vec2 posFee = vec2(gLune.x + 4.5*gAngleJour, gLune.y - .015 + .012*sin(gAngleJour*45.));
    float echelle = .05;
    vec2 q = (p - posFee)/echelle;
    float aa = 1.2/(iResolution.y*echelle);

    for(int i=0; i<8; i++){
        float fi = float(i);
        vec2 posPoussiere = posFee + vec2(-(.07 + .05*fi), .012*sin(t*6. + fi*1.7) - .004*fi - .02);
        float distPoussiere = length(p - posPoussiere);
        float scintillement = .6 + .4*sin(t*14. + fi*2.3);
        col += vec3(1., .82, .45) * exp(-distPoussiere*distPoussiere*40000.) * (1. - fi/8.) * scintillement * fenetre;
    }

    if(abs(q.x) > 4. || abs(q.y) > 3.) return col;

    float battement1 = sin(t*22.);
    float battement2 = sin(t*22. + .8);

    float dragon = sdSegment(q, vec2(-2.7, -.15), vec2(-.4, .02), .055);
    dragon = min(dragon, sdSegment(q, vec2(-.4, .02), vec2(.7, .12), .15));
    dragon = min(dragon, length(q - vec2(.95, .13)) - .17);

    float feeForme = sdSegment(q, vec2(.3, .28), vec2(.45, .62), .10);
    feeForme = min(feeForme, length(q - vec2(.5, .8)) - .13);
    feeForme = min(feeForme, sdSegment(q, vec2(.47, .88), vec2(.05, .80), .05));
    feeForme = min(feeForme, sdSegment(q, vec2(.3, .28), vec2(.58, .14), .05));
    feeForme = min(feeForme, sdSegment(q, vec2(.58, .14), vec2(.52, -.12), .04));
    feeForme = min(feeForme, sdSegment(q, vec2(.45, .6), vec2(.8, .5), .04));
    feeForme = min(feeForme, sdAile(q, vec2(.3, .3), 3.5, .4, .17));

    float ailes = sdAile(q, vec2(.15, .15), 1.55 + .4*battement1, 1.25, .2);
    ailes = min(ailes, sdAile(q, vec2(-.05, .12), 2.25 + .4*battement2, 1.3, .2));
    ailes = min(ailes, sdAile(q, vec2(.15, .10), -1.6 - .4*battement1, 1.2, .18));
    ailes = min(ailes, sdAile(q, vec2(-.05, .08), -2.3 - .4*battement2, 1.25, .18));
    ailes = min(ailes, sdAile(q, vec2(.4, .58), 2.0 + .5*battement1, .6, .14));
    ailes = min(ailes, sdAile(q, vec2(.4, .55), 2.7 + .5*battement2, .5, .12));

    float distSilhouette = min(dragon, feeForme);
    float masqueAile = 1. - smoothstep(-aa, aa, ailes);
    vec3 couleurAile = mix(vec3(.45, .75, 1.), vec3(1., .6, .95), clamp(q.y*.3 + .5, 0., 1.));
    col = mix(col, couleurAile, masqueAile*.38*fenetre);
    float anneau = smoothstep(-aa, aa, distSilhouette) * (1. - smoothstep(0., aa*4., distSilhouette));
    col += vec3(.55, .45, .95) * anneau * .45 * fenetre;
    col = mix(col, vec3(.012, .008, .03), (1. - smoothstep(-aa, aa, distSilhouette))*fenetre);
    return col;
}

vec3 ciel(vec2 p, float t, float cam)
{
    float v = clamp((p.y + .05)/.6, 0., 1.);
    vec3 col = mix(gHorizon, gMilieu, smoothstep(.0, .45, v));
    col = mix(col, gSommet, smoothstep(.35, 1., v));

    vec2 dh = (p - vec2(gSoleil.x, .0)) * vec2(1., 2.2);
    col += mix(vec3(1.,.5,.3), vec3(1.,.8,.6), gJour) * exp(-length(dh)*2.6) * gCrepuscule * .55;

    float cl = fbm(vec2(p.x*1.8 + t*.01 + cam*.05, p.y*5.));
    float masqueNuage = smoothstep(.5, .85, cl) * smoothstep(.0, .2, v) * (1. - smoothstep(.6, 1., v));
    vec3 couleurNuage = mix(vec3(.55,.28,.60), vec3(1.), gJour);
    couleurNuage = mix(couleurNuage, vec3(1.,.55,.40), gCrepuscule*.8);
    col = mix(col, couleurNuage*mix(.7, 1.1, gJour), masqueNuage*mix(.28, .6, gJour));

    vec2 sg = (p + vec2(cam*.02, 0.))*55.;
    vec2 sid = floor(sg);
    float sr = hachage21(sid);
    vec2 sf = fract(sg) - .5 - (hachage22(sid)-.5)*.6;
    float etoile = smoothstep(.07, .0, length(sf)) * step(.93, sr);
    etoile *= .6 + .4*sin(t*3. + sr*50.);
    col += vec3(.9,.9,1.) * etoile * smoothstep(.05, .4, v) * (1.-cl) * gNuit*gNuit;

    float ds = length(p - gSoleil);
    col = mix(col, gCouleurSoleil*1.6, 1. - smoothstep(.043, .048, ds));

    vec2 dv = p - gLune;
    float dm = length(dv);
    float disque = 1. - smoothstep(.07, .076, dm);
    float cratere = .85 + .3*(fbm(dv*18.) - .5);
    float entaille = 1. - smoothstep(.060, .068, length(dv - vec2(.034, .016)));
    float croissant = disque * (1. - entaille);
    col = mix(col, vec3(1.,.95,.85)*cratere*1.15, croissant*mix(.25, 1., gNuit));

    float a = fbm(vec2(p.x*1.5 + t*.05 + cam*.1, t*.03));
    float yy = p.y - .22 - .12*a - .05*sin(p.x*2. + t*.3);
    float bande = exp(-yy*yy*70.);
    float rideau = .65 + .35*sin(p.x*70. + a*12. + t*.5);
    vec3 aurore = mix(vec3(.2,1.,.65), vec3(.7,.3,1.), smoothstep(.0, .4, p.y));
    col += aurore * bande * rideau * .38 * smoothstep(-.05, .2, p.y) * gNuit*gNuit;
    col = fee(p, col, t);
    return col;
}

vec3 montagnes(vec2 p, vec3 col, float decalage, vec3 couleurMontagne, vec3 couleurBrouillard, float intensiteBrouillard)
{
    float x = p.x + decalage;
    float h = .03 + .17*fbm(vec2(x*1.2+3., 1.)) + .03*sin(x*.8);
    float m = 1. - smoothstep(-.004, .004, p.y - h);
    vec3 c = mix(palette(couleurMontagne), couleurBrouillard, intensiteBrouillard);
    c += mix(vec3(.9,.6,.9), gCouleurSoleil, gJour) * (1. - smoothstep(.0, .05, h - p.y)) * .12;
    return mix(col, c, m);
}

float hauteurHauteur(float x, float base, float graine, float amplitude){
    return base + amplitude*(.6*sin(x*2.3+graine*3.) + .4*sin(x*5.1+graine*1.7)) + amplitude*.5*bruit(vec2(x*3., graine));
}

vec3 foret(vec2 p, vec3 col, float decalage, float base, float taille, float graine,
           float densite, vec3 couleurSol, vec3 feuillageSombre, vec3 feuillageClair, vec3 couleurLueur,
           float intensiteBrouillard, vec3 couleurBrouillard, float t, float scintillement)
{
    couleurSol = palette(couleurSol); feuillageSombre = palette(feuillageSombre); feuillageClair = palette(feuillageClair);
    vec3 lueurNuit = couleurLueur * gNuit;

    float x = p.x + decalage;
    float amp = taille*.35;

    float g = hauteurHauteur(x, base, graine, amp);
    float m = 1. - smoothstep(-.004, .004, p.y - g);
    vec3 couleurG = mix(couleurSol, couleurBrouillard, intensiteBrouillard);
    couleurG += lueurNuit * (1. - smoothstep(.0, .03, g - p.y)) * .08 * (1.-intensiteBrouillard);
    couleurG += gCouleurSoleil * gJour * (1. - smoothstep(.0, .02, g - p.y)) * .10 * (1.-intensiteBrouillard);
    col = mix(col, couleurG, m);

    float largeurCellule = taille*3.2;
    float id0 = floor(x/largeurCellule);

    for(int k=-1; k<=1; k++){
        float id = id0 + float(k);
        float r  = hachage11(id*3.17 + graine*11.);
        if(r > densite) continue;
        float r2 = hachage11(id*7.31 + graine*5.);

        float xc    = (id + .25 + .5*r2)*largeurCellule;
        float base0 = hauteurHauteur(xc, base, graine, amp);
        float lx = x - xc;
        float ly = p.y - base0;
        float H  = taille*(2.0 + 1.2*r2);
        float R  = taille*(.85 + .3*r);

        float rafale = .5 + .5*sin(xc*1.5 - t*1.6);
        float osc = taille*(.10 + .12*rafale) * (.7 + .3*sin(t*2.3 + id*1.9));

        if(abs(lx) > R*1.9 + abs(osc) || ly < -.02 || ly > H + R*1.9) continue;

        float hn   = clamp(ly/H, 0., 1.4);
        float courbure = osc*hn*hn;
        float lxb  = lx - courbure;
        float largeurTronc = taille*(.07*(1.-.55*clamp(ly/H,0.,1.)) + .015);
        float tronc = (1.-smoothstep(largeurTronc*.75, largeurTronc, abs(lxb))) * step(0.,ly) * step(ly, H*1.02);
        vec3 couleurTronc = mix(feuillageSombre*.6, couleurBrouillard, intensiteBrouillard);
        col = mix(col, couleurTronc, tronc);

        vec2 q = vec2(lx - osc, ly - H);
        vec2 fluctuation = vec2(bruit(q/taille*7. + vec2(t*.9, t*.6)),
                                bruit(q/taille*7. + 9.1 + vec2(-t*.7, t*.8))) - .5;
        q += fluctuation * taille*.12*(.5 + rafale);

        float d1 = length(q) - R;
        float d2 = length(q - vec2(-.65*R, -.35*R)) - R*.70;
        float d3 = length(q - vec2( .65*R, -.25*R)) - R*.75;
        float d4 = length(q - vec2( .10*R,  .55*R)) - R*.60;
        float d  = min(min(d1,d2), min(d3,d4));
        d += (bruit(q/taille*14. + graine*3.) - .5)*taille*.18;

        float masqueFeuillage = 1. - smoothstep(-.006, .006, d);

        col += lueurNuit * exp(-max(d,0.)/(taille*.35)) * .10 * (1.-intensiteBrouillard);

        float ombrage = clamp(.5 + .6*dot(q/R, gDirectionLumiere) + .5*(bruit(q/taille*10.+3.)-.5), 0., 1.);
        vec3 couleurFeuille = mix(feuillageSombre, feuillageClair, ombrage*ombrage);
        float bord = 1. - smoothstep(-taille*.18, .0, d);
        couleurFeuille += lueurNuit * bord * .35 * ombrage;
        couleurFeuille += gCouleurSoleil * gJour * bord * .30 * ombrage;

        vec2 sg  = q/taille*18.;
        vec2 sid = floor(sg);
        float sr = hachage21(sid + id*13.);
        float etincelle = step(.9, sr) * (1.-smoothstep(.0,.3,length(fract(sg)-.5))) * (.5+.5*sin(t*4.+sr*60.));
        couleurFeuille += lueurNuit * etincelle * 2. * scintillement;

        col = mix(col, mix(couleurFeuille, couleurBrouillard, intensiteBrouillard), masqueFeuillage);
    }
    return col;
}

vec3 brume(vec2 p, vec3 col, float decalage, float yBase, float intensite, float t)
{
    float n  = fbm(vec2((p.x+decalage)*2.2 + t*.05, p.y*6.));
    float dy = (p.y - yBase)*4.5;
    vec3 couleurBrume = mix(vec3(.75,.5,.95), vec3(.9,.95,1.), gJour);
    couleurBrume = mix(couleurBrume, vec3(1.,.6,.5), gCrepuscule*.6);
    return col + couleurBrume * n * exp(-dy*dy) * intensite * .5 * mix(1., .6, gJour);
}

vec3 lucioles(vec2 p, vec3 col, float decalage, float echelle, float t, float luminosite)
{
    if(gNuit < .02) return col;
    vec2 g   = vec2(p.x + decalage, p.y)*echelle + vec2(0., t*.05);
    vec2 id  = floor(g);
    vec2 f   = fract(g) - .5;
    vec2 alea = hachage22(id + echelle);
    if(alea.x > .45) return col;
    vec2 pos = (alea-.5)*.3 + .08*vec2(sin(t*(.4+alea.x)+alea.y*6.28), cos(t*(.6+alea.y)+alea.x*6.28));
    float dn = length(f - pos);
    float scintillement = .5 + .5*sin(t*(2.+3.*alea.x) + alea.y*30.);
    float halo = pow(max(1.-dn/.17, 0.), 2.) + exp(-dn*dn*1800.)*1.5;
    vec3 couleurLucioles = mix(vec3(1.,.85,.4), vec3(1.,.5,.9), step(.4, alea.y));
    couleurLucioles = mix(couleurLucioles, vec3(.4,.9,1.), step(.7, alea.y));
    return col + couleurLucioles * halo * scintillement * luminosite * gNuit * .6;
}

vec3 mecheLanterne(vec2 p, vec3 col, float decalage, float t)
{
    float x = p.x + decalage;
    float S = .95;
    float id0 = floor(x/S);
    float amp = C_TAILLE*.35;
    float gPixel = hauteurHauteur(x, C_BASE, C_GRAINE, amp);
    float masqueSol = 1. - smoothstep(-.004, .004, p.y - gPixel);
    vec3 chaud = vec3(1., .68, .30);
    float HLampadaire = .17;

    for(int k=-1; k<=1; k++){
        float id = id0 + float(k);
        float r  = hachage11(id*5.13 + 71.);
        if(r > .75) continue;
        float r2 = hachage11(id*2.71 + 13.);
        float xc = (id + .3 + .4*r2)*S;
        float lx = x - xc;
        float base0 = hauteurHauteur(xc, C_BASE, C_GRAINE, amp);
        float ly = p.y - base0;
        if(abs(lx) > .6 || ly > HLampadaire + .6 || ly < -.5) continue;

        float allume = smoothstep(.35 + .25*r2, .50 + .25*r2, gNuit);
        allume *= .94 + .06*sin(t*9. + id*4.7)*sin(t*3.1 + id);

        vec2 posLanterne = vec2(lx, ly - HLampadaire - .03);
        float distLanterne = length(posLanterne);
        col += chaud * allume * (exp(-distLanterne*40.)*1.2 + exp(-distLanterne*14.)*.7 + exp(-distLanterne*5.)*.22);

        float haut = HLampadaire + .012;
        float dr   = clamp((haut - ly)/haut, 0., 1.);
        float demiLargeur = .015 + .15*dr;
        float cone = (1. - smoothstep(demiLargeur*.25, demiLargeur, abs(lx))) * step(0., ly) * step(ly, haut) * (1. - dr*.7);
        col += chaud * allume * cone * .10;

        float tacheSol = masqueSol * exp(-lx*lx*20.) * exp((p.y - gPixel)*20.);
        col += chaud * allume * tacheSol * .55;

        float largeurPoteau = .0032 + .0035*(1. - smoothstep(0., HLampadaire, ly)) + .010*(1. - smoothstep(0., .03, ly));
        largeurPoteau += .003*(1. - smoothstep(0., .004, abs(ly - .10)));
        largeurPoteau += .0025*(1. - smoothstep(0., .003, abs(ly - HLampadaire + .012)));
        float poteau = (1. - smoothstep(largeurPoteau*.7, largeurPoteau, abs(lx))) * step(0., ly) * step(ly, HLampadaire + .012);

        vec2 lc = vec2(lx, ly - HLampadaire - .03);
        vec2 bq = abs(lc) - vec2(.0085, .017);
        float dl = length(max(bq, 0.)) + min(max(bq.x, bq.y), 0.) - .005;
        float corpsLanterne = 1. - smoothstep(-.001, .001, dl);
        float verre = 1. - smoothstep(-.0045, -.0025, dl);
        float ry = lc.y - .021;
        float demiLargeurToit = .016*(1. - ry/.016);
        float toit = step(0., ry) * step(ry, .016) * (1. - smoothstep(demiLargeurToit*.9, demiLargeurToit, abs(lc.x)));

        vec3 couleurCadre = mix(vec3(.015,.015,.03), vec3(.12,.10,.14), gJour);
        couleurCadre = mix(couleurCadre, gHorizon*.3, .15);
        col = mix(col, couleurCadre, max(poteau, max(corpsLanterne, toit)));

        vec3 verreAllume  = chaud*(1.6 + .25*sin(t*20. + id));
        vec3 verreEteint = mix(vec3(.18,.20,.28), vec3(.55,.60,.70), gJour);
        col = mix(col, mix(verreEteint, verreAllume, allume), verre);
        float barre = 1. - smoothstep(.0007, .0015, abs(lc.x));
        col = mix(col, couleurCadre, verre*barre*.8);
        col += chaud * allume * verre * .6;
    }
    return col;
}

float hauteurPremierPlan(float x){
    return -.38 + .025*sin(x*1.7) + .018*sin(x*4.1+1.) + .012*bruit(vec2(x*5., 1.));
}

vec3 premierPlan(vec2 p, vec3 col, float decalage, float t)
{
    float x = p.x + decalage;
    float g = hauteurPremierPlan(x);
    float profondeur = clamp((g-p.y)*5., 0., 1.);
    vec3 couleurSol = mix(palette(vec3(.05,.17,.14)), palette(vec3(.006,.025,.035)), profondeur);
    float m = 1. - smoothstep(-.006, .006, p.y - g);
    col = mix(col, couleurSol, m);

    float emission = mix(.3, 1., gNuit);
    float cellules = 4.5;
    float xm = x*cellules;
    float mi = floor(xm);
    float r1 = hachage11(mi + 5.), r2 = hachage11(mi*1.7 + 9.);
    if(r1 > .3){
        float xc = (mi + .5)/cellules;
        float dx = (fract(xm) - .5)/cellules;
        float ly = p.y - hauteurPremierPlan(xc);
        float hauteurChampignon = .05 + .09*r2;
        float rayonChapeau     = .028 + .022*r1;
        vec2 q = vec2(dx/rayonChapeau, (ly-hauteurChampignon)/(rayonChapeau*.7));
        float distChapeau = length(q);
        float chapeau     = (1.-smoothstep(.92, 1., distChapeau)) * step(-.3, q.y);
        float pied        = (1.-smoothstep(.005, .008, abs(dx))) * step(0., ly) * step(ly, hauteurChampignon);
        vec3 couleurLumiere = mix(vec3(.2,.9,1.), vec3(1.,.4,.9), r2);
        float pulsion = .75 + .25*sin(t*1.5 + mi);
        col = mix(col, couleurLumiere*.3*mix(.6,1.,gNuit), pied);
        col = mix(col, couleurLumiere*(.9 + .4*clamp(q.y,0.,1.))*pulsion*1.3*emission, chapeau);
        col += couleurLumiere * exp(-max(distChapeau-.7, 0.)*3.) * .2 * pulsion * gNuit;
        col += couleurLumiere * .15 * pulsion * exp(-abs(dx)*25.) * exp(-abs(ly)*30.) * gNuit;
    }

    for(int k=0; k<2; k++){
        float kf  = float(k);
        float echelle = 34. + kf*26.;
        float gx  = x*echelle + kf*13.7;
        float gid = floor(gx);
        float r   = hachage11(gid + kf*91.);
        float hauteurBrin = (.035 + .075*r*r) * (1. + kf*.35);
        float lx  = (fract(gx) - .5)/echelle;
        float ly  = p.y - g + .008;
        float hn  = clamp(ly/hauteurBrin, 0., 1.);
        float rafale = .5 + .5*sin(x*2.2 - t*2.4);
        float courbure = (.004 + .008*rafale)*hn*hn + .0015*sin(t*5. + gid*1.3)*hn;
        float lxb  = lx - courbure - (r-.5)*.004;
        float largeur = .0035*(1. - hn*.9) + .0003;
        float masqueBrin = step(0., ly) * step(ly, hauteurBrin) * (1. - smoothstep(largeur*.4, largeur, abs(lxb)));
        vec3 couleurBrin = mix(palette(vec3(.01,.04,.04)), palette(vec3(.08,.30,.20)), hn);
        couleurBrin += mix(vec3(.3,.9,.7), gCouleurSoleil, gJour) * pow(hn,4.) * .15 * (1.-kf) * (gNuit*.8 + .4);
        couleurBrin = mix(couleurBrin, couleurBrin*.25, kf);
        col = mix(col, couleurBrin, masqueBrin);
    }
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 p = (fragCoord - .5*iResolution.xy) / iResolution.y;
    float t = iTime;

    configurerEclairage(t);

    vec2 souris = (iMouse.z > 0.) ? (iMouse.xy/iResolution.xy - .5)
                                 : vec2(.2*sin(t*.15), .1*sin(t*.11));
    float cam = t*.04 + souris.x*1.5;
    float ys  = souris.y*.05;

    vec3 brouillardLointain = gHorizon*.80;
    vec3 brouillardMoyen    = gHorizon*.55;
    vec3 brouillardProche   = gHorizon*.30;

    vec3 col = ciel(p, t, cam);

    col = montagnes(p + vec2(0., ys*.2), col, cam*.08, vec3(.33,.19,.50), gHorizon*.9, .55);

    col = foret(p + vec2(0., ys*.4), col, cam*.2, -.03, .035, 1., .8,
                vec3(.25,.14,.40), vec3(.22,.12,.38), vec3(.50,.30,.65), vec3(.9,.5,.9),
                .6, brouillardLointain, t, 0.);
    col = brume(p, col, cam*.2, -.05, .5, t);

    col = foret(p + vec2(0., ys*.6), col, cam*.5, -.12, .065, 2., .75,
                vec3(.12,.08,.25), vec3(.10,.07,.22), vec3(.30,.20,.50), vec3(.6,.7,1.),
                .35, brouillardMoyen, t, .3);
    col = lucioles(p, col, cam*.5, 9., t, .6);
    col = brume(p, col, cam*.5, -.2, .6, t);

    col = foret(p + vec2(0., ys), col, cam*1., C_BASE, C_TAILLE, C_GRAINE, .7,
                vec3(.03,.06,.12), vec3(.02,.05,.10), vec3(.12,.30,.40), vec3(.3,1.,.9),
                .08, brouillardProche, t, 1.);
    col = mecheLanterne(p + vec2(0., ys), col, cam*1., t);
    col = lucioles(p, col, cam*.9, 15., t, 1.);

    col = premierPlan(p + vec2(0., ys*1.5), col, cam*1.6, t);
    col = lucioles(p, col, cam*1.8, 5., t, .5);
    col = brume(p, col, cam*1.2, -.42, .6, t);

    col = 1. - exp(-col*mix(1.35, 1.15, gJour));
    col = mix(col, col*col*(3.-2.*col), .3);
    col += vec3(0., .01, .02) * (1.-col) * gNuit;
    col *= 1. - mix(.55, .35, gJour)*dot(p*.85, p*.85);
    col += (hachage21(fragCoord + fract(t)*100.) - .5)*.025;
    col = pow(max(col, 0.), vec3(.92));

    fragColor = vec4(col, 1.);
}
